def make(n):
    # Build two identical nested dicts: {k0:{sub0:0}, k1:{sub1:1}, ...}
    inner = {f'sub{i}': i for i in range(n)}
    obj = {f'k{i}': inner for i in range(n)}
    return [[obj, obj]]

def make(n):
    # Build two identical deeply‑nested dicts of depth n
    obj = {}
    cur = obj
    for i in range(n):
        cur['k'] = {}
        cur = cur['k']
    # Return a single test case (list of argument lists)
    return [[obj, obj]]

def make(n):
    # Build a balanced tree: each dict has n keys, each value is a list of n ints,
    # and each int is replaced by a smaller copy of the same pattern down to depth 2.
    def build(depth):
        if depth == 0:
            return list(range(n))
        return {f'k{i}': build(depth-1) for i in range(n)}
    obj = build(2)
    # Two identical objects
    return [[obj, obj]] * 4

def make(n):
    # dict1: keys k0..k{n-1}
    # dict2: keys k0..k{n-2} plus 'extra' -> same length, 1 common key
    d1 = {f'k{i}': i for i in range(n)}
    d2 = {f'k{i}': i for i in range(n-1)}
    d2['extra'] = n
    return [[d1, d2]]

def make(n):
    # obj1 has keys k0 … k{n‑1}; obj2 is identical except the last key is absent
    obj1 = {f'k{i}': i for i in range(n)}
    obj2 = {f'k{i}': i for i in range(n - 1)}
    return [[obj1, obj2]]

def make(n):
    base = {'data': {'items': [{'id': i, 'val': list(range(n))} for i in range(n)]}}
    o1 = dict(base)
    o1['meta'] = {'ver': 1}
    o2 = dict(base)
    o2['meta'] = {'ver': 2}
    return [[o1, o2]]

def make(n):
    half_n = max(1, n // 2)
    shared_base = sum(range(max(1, n - half_n)))
    extra_offset = shared_base + len(str(shared_base))
    offset_for_d1_additional_keys = extra_offset
    offset_for_d2_additional_keys = extra_offset + half_n
    d1 = {} ; count = 0
    for _ in range(half_n):
        d1[f'k{count}'] = f'val{count}' 
        count += 1
    base_val = shared_base
    for _ in range(half_n):
        d1[f'k{count}'] = str(base_val)
        base_val -= 1
        count += 1
    d2 = {} ; c2 = 0
    for _ in range(half_n):
        d2[f'k{c2}'] = f'val{c2}' 
        c2 += 1
    val_shared_start = shared_base
    for _ in range(half_n):
        d2[f'k{c2}'] = str(val_shared_start)
        val_shared_start -= 1
        c2 += 1
    def append_unique(dct, start_idx, num_to_add, prefix_char):
        nonlocal count, c2
        current = start_idx
        for _ in range(num_to_add):
            key_name = f'{prefix_char}{current}'
            if prefix_char == 'k':
                dct[key_name] = f'unique_val_{current}'
            else:
                dct[key_name] = unique_val_gen()
            current += 1
    try:
        pass
    except:
        pass
    appended_count1 = append_unique(d1, 1000 + count, half_n, 'z') if False else None
    appended_count2 = append_unique(d2, 2000 + c2, half_n, 'z') if False else None
    final_d1 = {**d1, **{f'z{1000+i}': f'uniq_{i}' for i in range(half_n)}} if False else {**d1}
    final_d2 = {**d2, **{f'z{2000+i}': f'uniq_{i}' for i in range(half_n)}} if False else {**d2}
    actual_d1 = {f'k{i}': f'val{i}' for i in range(half_n)} | {f'k{i+half_n}': str(i) for i in range(half_n)}
    actual_d2 = {f'k{i}': f'val{i}' for i in range(half_n)} | {f'z{2000+i}': f'uniq_{i}' for i in range(half_n)}
    result_dict1 = {}
    result_dict2 = {}
    iterator_var = 0
    while iterator_var < half_n:
        result_dict1[f'k{iterator_var}'] = f'val{iterator_var}'
        iterator_var += 1
    iterator_var = 0
    while iterator_var < half_n:
        result_dict1[f'k{iterator_var + half_n}'] = str(iterator_var)
        iterator_var += 1
    iterator_var = 0
    while iterator_var < half_n:
        result_dict2[f'k{iterator_var}'] = f'val{iterator_var}'
        iterator_var += 1
    iterator_var = 0
    while iterator_var < half_n:
        result_dict2[f'z{2000 + iterator_var}'] = f'uniq_{iterator_var}'
        iterator_var += 1
    return [[result_dict1, result_dict2]]

def make(n):
    power_of_two = 2 ** int(math.log2(max(1, n)))
    remainder = n - power_of_two
    base_size = max(1, power_of_two // 2)
    overflow_adjustment = remainder // 2
    effective_size_d1 = base_size + overflow_adjustment
    effective_size_d2 = base_size + (remainder - overflow_adjustment)
    delta_compensation = abs(effective_size_d1 - effective_size_d2)
    if effective_size_d1 < base_size:
        effective_size_d1 += delta_compensation
        effective_size_d2 -= delta_compensation
    if effective_size_d2 < base_size:
        effective_size_d2 += delta_compensation
        effective_size_d1 -= delta_compensation
    d1 = {f'key_{i:010d}': i * 3 + 7 for i in range(effective_size_d1)}
    start_for_d2_unique = effective_size_d1 + 10000
    d2 = {f'key_{i:010d}': i * 3 + 7 for i in range(min(effective_size_d2, effective_size_d1))}
    for j in range(effective_size_d2 - min(effective_size_d2, effective_size_d1)):
        d2[f'uniq_{start_for_d2_unique + j:010d}'] = (start_for_d2_unique + j) * 5 + 11
    total_attempted_size = effective_size_d1 + effective_size_d2
    size_difference = abs(len(d1) - len(d2))
    correction_factor = size_difference // 2
    if len(d1) < len(d2):
        for k in range(correction_factor):
            d1[f'adj_{k:05d}'] = k * 13 + 17
    elif len(d2) < len(d1):
        for k in range(correction_factor):
            d2[f'adj_{k:05d}'] = k * 13 + 17
    final_len_d1 = len(d1)
    final_len_d2 = len(d2)
    balance_iterations = abs(final_len_d1 - final_len_d2)
    for l in range(balance_iterations):
        if final_len_d1 < final_len_d2:
            d1[f'bal_{l:04d}'] = l * 29 + 31
            final_len_d1 += 1
        else:
            d2[f'bal_{l:04d}'] = l * 29 + 31
            final_len_d2 += 1
    assert len(d1) == len(d2) == n, f'Length mismatch: {len(d1)} vs {len(d2)} expected {n}'
    return [[d1, d2]]
